import time, subprocess, json, os
print('keep-alive + idle-watchdog running (60 min idle -> shutdown to save quota)', flush=True)
IDLE_LIMIT = 3600.0
last_pub = 0.0
try:
    _HALT
except NameError:          # cell 4 never got as far as defining it
    _HALT = {'on': False}
_reason = 'completed'
while True:
    # Sleep in short slices. A shutdown request used to wait for the whole
    # 60-second tick, which is most of the delay a user feels when pressing
    # the off button.
    for _ in range(12):
        if _HALT.get('on'):
            break
        time.sleep(5)
    if _HALT.get('on'):
        _reason = 'shutdown requested from the app'
        break
    try:
        subprocess.run(['curl', '-s', '-m', '20', 'http://127.0.0.1:11434/api/generate', '-d', json.dumps({'model': open('/kaggle/working/MODEL.txt').read().strip(), 'prompt': 'ping', 'stream': False, 'options': {'num_predict': 1, 'num_ctx': globals().get('NUM_CTX', 16384)}, 'keep_alive': -1})], capture_output=True, timeout=90)
    except Exception:
        pass
    now = time.time()
    if now - last_pub > 600:
        try:
            link = open('/kaggle/working/CHAT_LINK.txt').read().strip()
            if link.startswith('https://'):
                def _ntfy(m):
                    subprocess.Popen(['curl', '-s', '-m', '10', '-d', m[:2500], 'https://ntfy.sh/{{AETHER_BEACON_TOPIC}}'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    subprocess.Popen(['curl', '-s', '-m', '10', '-d', m[:2500], 'https://webhook.site/{{AETHER_BEACON_TOKEN}}'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                _ntfy('engine=' + SLOT + ' alive: ' + link + ' (idle ' + str(int((now - LAST_HIT["t"]) // 60)) + ' min)')
                last_pub = now
        except Exception:
            pass
    idle = now - LAST_HIT['t']
    if idle > IDLE_LIMIT:
        try:
            subprocess.run(['curl', '-s', '-m', '10', '-d', 'IDLE SHUTDOWN after 60 min without chat - quota saved. Send a message to wake.', 'https://ntfy.sh/{{AETHER_BEACON_TOPIC}}'], capture_output=True, timeout=15)
        except Exception:
            pass
        print('IDLE SHUTDOWN', flush=True)
        _reason = 'idle for 60 minutes'
        break

# Returning from the last cell is what ends the Kaggle run and hands the GPU
# back. os._exit(0) does not: the kernel was still reported as "running" 50
# minutes after /off killed the process, still holding its session.
print('NOTEBOOK COMPLETE (' + _reason + ') - GPU session released', flush=True)
